1	import 'dart:async';
2	
3	import 'package:flutter_bloc/flutter_bloc.dart';
4	import 'package:fpdart/fpdart.dart';
5	
6	import '../../../../core/failure/failure.dart';
7	import '../../../../core/isolated_side_effect.dart';
8	import '../../../entries/domain/entities/entry.dart';
9	import '../../../entries/domain/usecases/save_chat_message_as_entry_use_case.dart';
10	import '../../domain/entities/bookmark_state.dart';
11	import '../../domain/entities/chat_insight.dart';
12	import '../../domain/entities/chat_message.dart';
13	import '../../domain/entities/chat_session.dart';
14	import '../../domain/entities/chat_stream_event.dart';
15	import '../../domain/insight_trigger_config.dart';
16	import '../../domain/repositories/chat_repository.dart';
17	import '../../domain/services/connectivity_watcher.dart';
18	import 'chat_state.dart';
19	
20	/// Drives `ChatScreen` — a DI `lazySingleton` (Code Map, mirroring
21	/// `MeusRegistrosCubit`): long-lived, so returning to Home/Chat within the
22	/// same app session never re-bootstraps the session/history it already
23	/// loaded (`init()`'s own no-op guard below).
24	class ChatCubit extends Cubit<ChatState> {
25	  ChatCubit(
26	    this._repository,
27	    this._connectivityWatcher,
28	    this._saveChatMessageAsEntryUseCase, {
29	    // spec-6-5 Design Notes: "the inactivity Duration is constructor-
30	    // overridable purely for test speed (no fake_async dependency exists
31	    // in this project)" — production never passes this, so the default
32	    // (the real 2-minute constant) is always what runs; no
33	    // `chat_injection.dart` change needed.
34	    Duration insightInactivityTimeout = defaultInsightInactivityTimeout,
35	  }) : _insightTimeout = insightInactivityTimeout,
36	       super(const ChatBootstrapLoading()) {
37	    // spec-6-3 — subscribes immediately (not gated on bootstrap), so the
38	    // very first connectivity read is never missed while a slow
39	    // `init()` is still in flight; `_handleConnectivityChange` itself is
40	    // a no-op against anything but `ChatReady` until bootstrap resolves,
41	    // `_isOffline` still being tracked below so a later `ChatReady`
42	    // (bootstrap, `switchSession`, `startNewSession`) picks up whatever
43	    // the device's status already was.
44	    _connectivitySubscription = _connectivityWatcher.watch().listen(
45	      _handleConnectivityChange,
46	      onError: (Object _, StackTrace _) {
47	        // RNF09: a connectivity-watch error (e.g. the platform channel
48	        // being unavailable — no device/simulator exists yet, AGENTS.md)
49	        // must never escape the cubit; `_isOffline` simply keeps
50	        // whatever value it last had (`false` if this is the very first
51	        // read) instead of crashing.
52	      },
53	    );
54	  }
55	
56	  final ChatRepository _repository;
57	  final ConnectivityWatcher _connectivityWatcher;
58	
59	  /// spec-6-4 (RF10) — the shared use case AGENTS.md's RF10 rule requires;
60	  /// never `EntriesRepository`, never anything under `entries/data/`/
61	  /// `entries/presentation/` (Boundaries).
62	  final SaveChatMessageAsEntryUseCase _saveChatMessageAsEntryUseCase;
63	
64	  StreamSubscription<bool>? _connectivitySubscription;
65	
66	  StreamSubscription<Either<Failure, ChatStreamEvent>>? _sendSubscription;
67	
68	  /// The in-flight [sendMessage]/[retryMessage]'s own completer, if any —
69	  /// [close] must complete it itself, since cancelling [_sendSubscription]
70	  /// alone never fires `onDone`/`onError` (review fix: `cancel()` alone
71	  /// left `sendMessage()`'s returned `Future` permanently unresolved when
72	  /// the cubit closed mid-send).
73	  Completer<void>? _sendCompleter;
74	
75	  /// Monotonic counter behind every locally generated [ChatUiMessage.id]
76	  /// (Code Map) — never the server's own message id (see `ChatStreamEvent`'s
77	  /// own doc on why `message_created`'s id goes unused here).
78	  int _localIdCounter = 0;
79	
80	  /// Whether a send/retry is actively in flight right now — tracked
81	  /// locally rather than by scanning [ChatState.messages] for a persisted
82	  /// `streaming` status, since a message loaded from history/cache can
83	  /// legitimately carry that same status (e.g. one left over from an
84	  /// earlier dropped response, the I/O matrix's own scenario) without a
85	  /// send actually being in progress; scanning for it would permanently
86	  /// disable the composer in that case. [retryMessage] reuses this exact
87	  /// guard verbatim (Boundaries: "a second retry while one is in flight —
88	  /// reuses `_isSending` verbatim"), so a retry and a send can never race
89	  /// each other either.
90	  bool _isSending = false;
91	
92	  /// An in-flight bootstrap, if any — reused by a concurrent `init()` call
93	  /// instead of starting a second bootstrap, so two near-simultaneous
94	  /// callers (e.g. two mounts before the first resolves) never both
95	  /// observe "no sessions" and both call `createSession()` (Boundaries:
96	  /// "silently ensure *one* Chat Session exists").
97	  Future<void>? _initFuture;
98	
99	  /// spec-6-3 — the device's last known online/offline status, as
100	  /// reported by [_connectivityWatcher], `true` meaning offline. Tracked
101	  /// independently of [ChatState] (unlike `_isSending`'s own UI-facing
102	  /// twin, [ChatReady.isOffline]) so a status learned before bootstrap
103	  /// resolves — or while the active session is being switched, neither of
104	  /// which touches this field — is never lost; every place that emits a
105	  /// fresh [ChatReady] (`_bootstrap`, [switchSession], [startNewSession])
106	  /// carries it forward explicitly.
107	  bool _isOffline = false;
108	
109	  /// Boundaries: "Scroll-offset restore is in-memory only, keyed by
110	  /// `sessionId`, on `ChatCubit` (never Hive) — survives session switches
111	  /// within one app run, resets on restart." Lives on this long-lived
112	  /// `lazySingleton` cubit itself (Design Notes), never on [ChatReady] —
113	  /// a state value would otherwise have to be threaded through every
114	  /// unrelated `copyWith` call just to avoid losing it.
115	  final Map<String, double> _scrollOffsets = {};
116	
117	  /// Review fix (round 2) — [bookmarkMessage]'s own save outcome, keyed
118	  /// by the message's `serverId` (never the in-session [ChatUiMessage.id],
119	  /// which is only a local id until the server confirms it, Design Notes)
120	  /// so a save that resolves *after* the user has switched/started a
121	  /// session — [switchSession]/[startNewSession] replace [ChatReady.
122	  /// messages] wholesale and never cancel a bookmark save in flight,
123	  /// unlike [_cancelInFlightSend] for send/retry — is never silently
124	  /// dropped. [_fromDomain] applies it when a session's history is
125	  /// (re)loaded; same in-memory-only, never-persisted-across-restarts
126	  /// lifetime as [_scrollOffsets] above (Boundaries).
127	  final Map<String, BookmarkState> _bookmarkStateByServerId = {};
128	
129	  /// spec-6-5 — the per-session trigger-window timeout racing
130	  /// [insightMessageCountThreshold] (Boundaries); overridable only via
131	  /// the constructor's own test seam (Design Notes).
132	  final Duration _insightTimeout;
133	
134	  /// spec-6-5 — user messages sent via [sendMessage] only (never
135	  /// [retryMessage], Boundaries) since the current trigger window
136	  /// opened. Reset to `0` every time a window closes, by either trigger.
137	  int _insightMessagesSinceWindowStart = 0;
138	
139	  /// spec-6-5 — the current window's own inactivity side of the race;
140	  /// cancelled/restarted on every [sendMessage] call and every window
141	  /// close (Boundaries) — a single field, never a per-session map,
142	  /// because only one session is ever active/racing at a time
143	  /// ([switchSession]/[startNewSession] always reopen a fresh window for
144	  /// whichever session becomes active, Boundaries: "never let the
145	  /// counter/timer leak across sessions").
146	  Timer? _insightInactivityTimer;
147	
148	  /// spec-6-5 — the current window's own client-generated key, echoed to
149	  /// `chat-insight-create` as `triggerKey` (Design Notes: "the contract
150	  /// only requires minLength: 1 with no documented semantics beyond
151	  /// echoing it back").
152	  String _insightTriggerKey = '';
153	
154	  /// spec-6-5 — monotonic counter behind every freshly generated
155	  /// [_insightTriggerKey], mirrors [_localIdCounter]/[_nextLocalId].
156	  int _insightWindowCounter = 0;
157	
158	  /// Review fix: a monotonic counter bumped once per [_fireInsightTrigger]
159	  /// call, so [_applyInsightResult] can tell whether the result it just
160	  /// received still belongs to the most recently fired request. A window
161	  /// reopens (and can fire again) immediately after the previous one
162	  /// fires, before that previous call's own response has necessarily
163	  /// arrived — without this guard, two overlapping in-flight calls for
164	  /// the *same* session could resolve out of order, letting a stale
165	  /// (older) result overwrite a newer `activeInsight`, or resurrect one
166	  /// the user already dismissed. Unlike [_insightTriggerKey] (which
167	  /// identifies *which window* a request was for for the backend's own
168	  /// idempotency), this identifies *recency* across overlapping requests
169	  /// for the cubit's own purposes — the backend is never told about it.
170	  int _insightRequestSeq = 0;
171	
172	  /// Boundaries: "On opening Home/Chat, silently ensure one Chat Session
173	  /// exists (reuse the most recent from `chat-sessions-list`, else
174	  /// `chat-sessions-create` with no title)". A no-op once already
175	  /// [ChatReady] — `ChatScreen.initState()` calls this unconditionally on
176	  /// every mount, but a `lazySingleton` cubit may already be bootstrapped
177	  /// from an earlier visit.
178	  Future<void> init() {
179	    if (state is ChatReady || isClosed) {
180	      return Future.value();
181	    }
182	    return _initFuture ??= _bootstrap().whenComplete(() => _initFuture = null);
183	  }
184	
185	  Future<void> _bootstrap() async {
186	    emit(const ChatBootstrapLoading());
187	
188	    final sessionsResult = await _repository.listSessions();
189	    if (isClosed) {
190	      return;
191	    }
192	    // Captured by the closures below so the resulting [ChatReady] can
193	    // carry every known session (Code Map: "capture resolved sessions
194	    // into the emitted ChatReady"), not just the one picked to reuse.
195	    List<ChatSession> sessions = const [];
196	    final Either<Failure, ChatSession> sessionResult = await sessionsResult
197	        .match((failure) async => left(failure), (fetchedSessions) async {
198	          if (fetchedSessions.isEmpty) {
199	            final createResult = await _repository.createSession();
200	            return createResult.match((failure) => left(failure), (session) {
201	              sessions = [session];
202	              return right(session);
203	            });
204	          }
205	          sessions = fetchedSessions;
206	          // "reuse the most recent" — defensively re-sorts rather than
207	          // trusting `listSessions()`'s own ordering (its offline-cache
208	          // fallback already sorts `updatedAt` desc, but the live
209	          // server response's own ordering isn't documented either
210	          // way). `tryParse` (never `parse`) — same crash-safe pattern as
211	          // `AppDrawer`'s own session sort (review finding "Crash risk in
212	          // the new `_ConversasSection` sort"): a malformed `updatedAt`
213	          // must never crash bootstrap itself, so it falls back to the
214	          // epoch and simply sorts last instead of throwing.
215	          final mostRecent = [...fetchedSessions]
216	            ..sort(
217	              (a, b) => (DateTime.tryParse(b.updatedAt) ?? DateTime(0))
218	                  .compareTo(DateTime.tryParse(a.updatedAt) ?? DateTime(0)),
219	            );
220	          return right(mostRecent.first);
221	        });
222	    if (isClosed) {
223	      return;
224	    }
225	
226	    await sessionResult.match(
227	      (failure) async {
228	        if (!isClosed) {
229	          emit(ChatBootstrapError(failure));
230	        }
231	      },
232	      (session) async {
233	        final messagesResult = await _repository.listMessages(session.id);
234	        if (isClosed) {
235	          return;
236	        }
237	        messagesResult.match((failure) => emit(ChatBootstrapError(failure)), (
238	          messages,
239	        ) {
240	          // spec-6-5 — opens this cubit's very first trigger window,
241	          // tied to the session this bootstrap settled on.
242	          _resetInsightWindow(session.id);
243	          emit(
244	            ChatReady(
245	              sessionId: session.id,
246	              messages: messages.map(_fromDomain).toList(),
247	              sessions: sessions,
248	              isOffline: _isOffline,
249	            ),
250	          );
251	        });
252	      },
253	    );
254	  }
255	
256	  /// Boundaries: "Scroll-offset restore is in-memory only, keyed by
257	  /// `sessionId`" — `ChatScreen`'s own `ScrollController` listener calls
258	  /// this on every scroll update, so whichever offset a session was last
259	  /// left at is always the one [switchSession] hands back when that
260	  /// session becomes active again.
261	  void recordScrollOffset(String sessionId, double offset) {
262	    _scrollOffsets[sessionId] = offset;
263	  }
264	
265	  /// I/O matrix: "Switch session"/"Switch to already-active session" —
266	  /// a no-op [Right] when [sessionId] is already [ChatReady.sessionId]
267	  /// (the drawer still closes, nothing reloads/re-fetches); otherwise
268	  /// fetches that session's own history via `listMessages` (reused as-is,
269	  /// Code Map) and makes it active, handing [ChatReady.restoreScrollOffset]
270	  /// whatever [recordScrollOffset] last captured for it (`null` if this
271	  /// session was never scrolled in this app run — `ChatScreen`'s own cue
272	  /// to jump to the bottom instead). A no-op while bootstrap hasn't
273	  /// resolved yet, same guard shape as [sendMessage].
274	  Future<Either<Failure, Unit>> switchSession(String sessionId) async {
275	    final current = state;
276	    if (current is! ChatReady) {
277	      return right(unit);
278	    }
279	    if (sessionId == current.sessionId) {
280	      return right(unit);
281	    }
282	    // Review finding: "Cross-session stream leakage" — an AI response
283	    // still streaming into the *old* session must never be left running
284	    // once we switch away from it; its orphaned subscription's
285	    // `onData`/`onDone` would otherwise go on to mutate whichever session
286	    // becomes active next.
287	    await _cancelInFlightSend();
288	    final messagesResult = await _repository.listMessages(sessionId);
289	    if (isClosed) {
290	      return right(unit);
291	    }
292	    return messagesResult.match(
293	      (failure) {
294	        // Review fix: `_cancelInFlightSend()` above only resets the
295	        // internal `_isSending` guard, not the `ChatReady.isSending` the
296	        // composer gates on (`canSend = ... && !state.isSending`) — on a
297	        // failed switch we're staying on `current`, so its stale
298	        // `isSending: true` must be flipped back here or the composer
299	        // would stay disabled for the rest of the app run.
300	        if (!isClosed && current.isSending) {
301	          emit(current.copyWith(isSending: false));
302	        }
303	        return left(failure);
304	      },
305	      (messages) {
306	        if (!isClosed) {
307	          // spec-6-5 — reopens a fresh trigger window for the session
308	          // becoming active, so the previous session's own window
309	          // (counter/timer) never leaks across the switch (Boundaries).
310	          _resetInsightWindow(sessionId);
311	          emit(
312	            ChatReady(
313	              sessionId: sessionId,
314	              messages: messages.map(_fromDomain).toList(),
315	              sessions: current.sessions,
316	              restoreScrollOffset: _scrollOffsets[sessionId],
317	              isOffline: _isOffline,
318	            ),
319	          );
320	        }
321	        return right(unit);
322	      },
323	    );
324	  }
325	
326	  /// I/O matrix: "New session online"/"New session offline" — calls
327	  /// `createSession()` (reused as-is, Code Map; already blocked offline
328	  /// at the repository level, Boundaries). On any [Left] (including
329	  /// [Failure.networkOffline]), the current session is left completely
330	  /// untouched — no state is emitted at all, only the [Failure] is handed
331	  /// back for `AppDrawer` to surface as a transient `SnackBar`
332	  /// (Boundaries). On success, the new session opens empty and becomes
333	  /// active, prepended to [ChatReady.sessions].
334	  Future<Either<Failure, Unit>> startNewSession() async {
335	    final current = state;
336	    if (current is! ChatReady) {
337	      return right(unit);
338	    }
339	    // Review finding: "Cross-session stream leakage" — same rationale as
340	    // [switchSession]'s own cancellation above; a brand new session is
341	    // never the same session as [current], so this always needs to run
342	    // (unlike [switchSession], there's no same-session no-op branch to
343	    // skip it for).
344	    await _cancelInFlightSend();
345	    final result = await _repository.createSession();
346	    if (isClosed) {
347	      return right(unit);
348	    }
349	    return result.match(
350	      (failure) {
351	        // Review fix: same stuck-`isSending` risk as [switchSession] — a
352	        // failed `createSession()` leaves `current` active, so its stale
353	        // `isSending: true` (left behind by `_cancelInFlightSend()`
354	        // above, which never emits) must be flipped back here.
355	        if (!isClosed && current.isSending) {
356	          emit(current.copyWith(isSending: false));
357	        }
358	        return left(failure);
359	      },
360	      (session) {
361	        if (!isClosed) {
362	          // spec-6-5 — same rationale as [switchSession] above: a brand
363	          // new session always needs its own fresh trigger window.
364	          _resetInsightWindow(session.id);
365	          emit(
366	            ChatReady(
367	              sessionId: session.id,
368	              messages: const [],
369	              sessions: [session, ...current.sessions],
370	              isOffline: _isOffline,
371	            ),
372	          );
373	        }
374	        return right(unit);
375	      },
376	    );
377	  }
378	
379	  ChatUiMessage _fromDomain(ChatMessage message) => ChatUiMessage(
380	    id: message.id,
381	    role: message.role,
382	    content: message.content,
383	    status: message.status,
384	    // spec-6-3 — every message reloaded from `chat-messages-list`/the
385	    // offline cache already has a persisted server id (unlike a message
386	    // created locally mid-session, which only gains one once/if
387	    // `message_created` arrives, Design Notes); [retryMessage] reads this
388	    // off the *user* message immediately preceding a `failed` AI bubble.
389	    serverId: message.id,
390	    createdAt: message.createdAt,
391	    // Review fix (round 2) — re-applies a bookmark save's outcome that
392	    // resolved while this message wasn't part of the live `ChatReady`
393	    // (session switched away mid-save); `idle` default when nothing was
394	    // ever recorded for this `serverId`.
395	    bookmarkState:
396	        _bookmarkStateByServerId[message.id] ?? const BookmarkState.idle(),
397	  );
398	
399	  /// Boundaries: optimistic user bubble, then subscribes to
400	  /// `ChatRepository.sendMessage`'s own stream, appending tokens as they
401	  /// arrive and finalizing/failing the AI bubble on `done`/any `Left` —
402	  /// the bubble's own [ChatUiMessage.content] is never cleared on failure
403	  /// (I/O matrix), only its [ChatUiMessage.status] changes.
404	  ///
405	  /// A no-op while [state] isn't [ChatReady] (bootstrap still in flight
406	  /// or failed — the composer is disabled in that case anyway), while
407	  /// [content] is blank once trimmed, while [_isSending] is already
408	  /// true — this story never races two concurrent sends against the one
409	  /// in-memory session — or while [ChatReady.isOffline] (review finding:
410	  /// the offline lock was UI-only via `_ChatComposer.canSend`, but nothing
411	  /// stopped a direct `sendMessage` caller from firing a real network call
412	  /// while the offline banner's own "novas mensagens bloqueadas" copy says
413	  /// otherwise). Deliberately not keyed off any loaded message's
414	  /// persisted `streaming` status — a message restored from history/cache
415	  /// can legitimately carry that status without a send actually being in
416	  /// flight (I/O matrix: mid-stream drop).
417	  Future<void> sendMessage(String content) async {
418	    final trimmed = content.trim();
419	    if (trimmed.isEmpty) {
420	      return;
421	    }
422	    final current = state;
423	    if (current is! ChatReady) {
424	      return;
425	    }
426	    if (_isSending || current.isOffline) {
427	      return;
428	    }
429	    _isSending = true;
430	
431	    // spec-6-5 — counts only a genuine sendMessage() call (never
432	    // retryMessage, Boundaries: "a counter ... never retryMessage").
433	    // Whichever of the two trigger conditions is satisfied first wins
434	    // the race for this window; reaching the threshold here fires
435	    // immediately rather than waiting for the inactivity timer to also
436	    // elapse.
437	    _insightMessagesSinceWindowStart++;
438	    if (_insightMessagesSinceWindowStart >= insightMessageCountThreshold) {
439	      _fireInsightTrigger(current.sessionId, InsightTriggerType.messageCount);
440	    } else {
441	      // Counter/key untouched (Code Map) — only the inactivity side of
442	      // the race restarts, so the window itself stays open.
443	      _restartInsightInactivityTimer(current.sessionId);
444	    }
445	
446	    final userMessage = ChatUiMessage(
447	      id: _nextLocalId(),
448	      role: ChatMessageRole.user,
449	      content: trimmed,
450	      status: ChatMessageStatus.complete,
451	    );
452	    final aiMessage = ChatUiMessage(
453	      id: _nextLocalId(),
454	      role: ChatMessageRole.assistant,
455	      content: '',
456	      status: ChatMessageStatus.streaming,
457	    );
458	    emit(
459	      current.copyWith(
460	        messages: [...current.messages, userMessage, aiMessage],
461	        isSending: true,
462	      ),
463	    );
464	
465	    await _consumeStream(
466	      _repository.sendMessage(current.sessionId, trimmed),
467	      userMessageId: userMessage.id,
468	      aiMessageId: aiMessage.id,
469	    );
470	  }
471	
472	  /// spec-6-3 — Boundaries: "Retry resets the *same* bubble (id,
473	  /// position) to `streaming`/empty, then reuses `_applyStreamEvent`/
474	  /// `_markFailed` unchanged — never a second bubble, never a duplicate
475	  /// question." [aiMessageId] must identify an existing `failed` AI
476	  /// bubble; anything else (not found, not `failed`, no preceding user
477	  /// message — shouldn't structurally happen) is a silent no-op, same
478	  /// defensive shape [sendMessage]'s own guards use.
479	  ///
480	  /// Keyed by the preceding user message's [ChatUiMessage.serverId]
481	  /// (Boundaries: "keyed by the user message's persisted id") — calls
482	  /// `ChatRepository.retryMessage` when it's known, or falls back to a
483	  /// full [ChatRepository.sendMessage] resend of that same user content
484	  /// into this exact AI bubble slot when it's `null` (I/O matrix: "Tap
485	  /// retry, no `serverId`" — the stream dropped before `message_created`
486	  /// ever arrived, so the backend never actually persisted the question;
487	  /// Boundaries: "Never calling `chat-messages-retry` with no `serverId`").
488	  /// Reuses [_isSending] verbatim (Boundaries: "A second retry while one
489	  /// is in flight"), so this is a no-op while a send/retry is already in
490	  /// flight — and, like [sendMessage] (review finding), a no-op while
491	  /// [ChatReady.isOffline] too: a failed bubble's retry tap is a separate
492	  /// affordance from the composer, not covered by `_ChatComposer.canSend`
493	  /// alone, so it needs this exact same guard to honor the offline banner.
494	  Future<void> retryMessage(String aiMessageId) async {
495	    final current = state;
496	    if (current is! ChatReady) {
497	      return;
498	    }
499	    if (_isSending || current.isOffline) {
500	      return;
501	    }
502	    final messages = current.messages;
503	    final aiIndex = messages.indexWhere((message) => message.id == aiMessageId);
504	    // Review finding: defensively checks `role` too, even though only an
505	    // assistant message ever reaches `failed` status today — matches this
506	    // guard clause's own already-defensive shape (`aiIndex == -1`, a
507	    // not-found/structurally-impossible case).
508	    if (aiIndex == -1 ||
509	        messages[aiIndex].role != ChatMessageRole.assistant ||
510	        messages[aiIndex].status != ChatMessageStatus.failed) {
511	      return;
512	    }
513	    ChatUiMessage? userMessage;
514	    for (var i = aiIndex - 1; i >= 0; i--) {
515	      if (messages[i].role == ChatMessageRole.user) {
516	        userMessage = messages[i];
517	        break;
518	      }
519	    }
520	    if (userMessage == null) {
521	      return;
522	    }
523	
524	    _isSending = true;
525	    emit(
526	      current.copyWith(
527	        messages: [
528	          for (final message in current.messages)
529	            if (message.id == aiMessageId)
530	              message.copyWith(content: '', status: ChatMessageStatus.streaming)
531	            else
532	              message,
