549	  /// Shared by [sendMessage]/[retryMessage] (Code Map: "extract shared ...
550	  /// helper" extends to this subscribe-and-wait shape too, not just
551	  /// `ChatRemoteDataSource`'s own SSE buffering) — subscribes to [stream],
552	  /// routing every emission through [_applyStreamEvent]/[_markFailed], and
553	  /// resolves once the stream ends (`done`, an in-band error, or a
554	  /// stream-level error), clearing [_isSending]/[ChatReady.isSending]
555	  /// either way via [_finishSending].
556	  Future<void> _consumeStream(
557	    Stream<Either<Failure, ChatStreamEvent>> stream, {
558	    required String userMessageId,
559	    required String aiMessageId,
560	  }) async {
561	    await _sendSubscription?.cancel();
562	    final completer = Completer<void>();
563	    _sendCompleter = completer;
564	    _sendSubscription = stream.listen(
565	      (event) {
566	        event.match(
567	          (failure) => _markFailed(aiMessageId),
568	          (streamEvent) =>
569	              _applyStreamEvent(userMessageId, aiMessageId, streamEvent),
570	        );
571	      },
572	      onError: (Object _, StackTrace _) {
573	        // RNF09: no exception escapes the cubit — a stream-level error
574	        // (shouldn't happen, `ChatRemoteDataSource` never lets one through
575	        // unmapped) still only fails the bubble, never crashes.
576	        _markFailed(aiMessageId);
577	        _finishSending();
578	        if (!completer.isCompleted) {
579	          completer.complete();
580	        }
581	        // Review finding: a stale, already-done subscription reference
582	        // left on `_sendSubscription` made a *later* send/retry's own
583	        // `await _sendSubscription?.cancel()` above hang indefinitely in
584	        // practice (observed via a widget test driving two sends back to
585	        // back) — cleared here (and in the `onDone` branch below)
586	        // exactly where this stream's own lifecycle actually ends,
587	        // rather than relying on cancelling an already-finished
588	        // subscription being an instant no-op.
589	        _sendSubscription = null;
590	        _sendCompleter = null;
591	      },
592	      onDone: () {
593	        _finishSending();
594	        if (!completer.isCompleted) {
595	          completer.complete();
596	        }
597	        _sendSubscription = null;
598	        _sendCompleter = null;
599	      },
600	      cancelOnError: false,
601	    );
602	    await completer.future;
603	  }
