605	  /// Clears both the internal re-entrancy guard and the UI-facing
606	  /// [ChatReady.isSending] signal once a send's stream has ended (`done`,
607	  /// an in-band error, or a stream-level error) — the single place both
608	  /// flip back together.
609	  void _finishSending() {
610	    _isSending = false;
611	    if (isClosed) {
612	      return;
613	    }
614	    final current = state;
615	    if (current is ChatReady) {
616	      emit(current.copyWith(isSending: false));
617	    }
618	  }
