924	      (failure) => left(failure),
925	      (inner) => inner,
926	    );
927	    final insight = flattened.match((_) => null, (insight) => insight);
928	    if (insight == null || isClosed || requestSeq != _insightRequestSeq) {
929	      return;
930	    }
931	    final current = state;
932	    if (current is! ChatReady || current.sessionId != sessionId) {
933	      return;
934	    }
935	    emit(current.copyWith(activeInsight: insight));
