94	        // discarding every other valid message in the response — same
95	        // per-item isolation the offline-cache fallback already applies.
96	        final dtos = <ChatMessageDto>[];
97	        for (final item in data) {
98	          try {
99	            dtos.add(ChatMessageDto.fromJson(item as Map<String, dynamic>));
100	          } catch (_) {
101	            // Skip this one malformed item.
102	          }
103	        }
104	        // Review fix: same "all items malformed" rationale as
105	        // listSessions() above — a non-empty response that fully fails
106	        // to decode must never be mistaken for "no messages", or a
107	        // session's whole history would silently render empty.
108	        if (data.isNotEmpty && dtos.isEmpty) {
109	          return left(
110	            Failure.malformedResponse(
111	              message: 'All items in listMessages() response failed to decode',
112	            ),
113	          );
114	        }
115	        return right(dtos);
116	      } catch (error) {
117	        return left(Failure.malformedResponse(message: error.toString()));
118	      }
119	    });
120	  }
