18	/// On success, [listSessions]/[createSession]/[listMessages] each write
19	/// through to their own Hive box *before* returning `right(...)`, same
20	/// "persist then return" ordering `EntriesRepositoryImpl` already uses.
21	class ChatRepositoryImpl implements ChatRepository {
22	  ChatRepositoryImpl({
23	    required ChatRemoteDataSource remoteDataSource,
24	    required Box<Map> sessionsBox,
25	    required Box<Map> messagesBox,
26	  }) : _remoteDataSource = remoteDataSource,
27	       _sessionsBox = sessionsBox,
28	       _messagesBox = messagesBox;
29	
30	  final ChatRemoteDataSource _remoteDataSource;
31	  final Box<Map> _sessionsBox;
32	  final Box<Map> _messagesBox;
33	
34	  @override
35	  Future<Either<Failure, List<ChatSession>>> listSessions() async {
36	    final result = await _remoteDataSource.listSessions();
37	    return result.match(
38	      (failure) async {
39	        // `requirements.md`: "`GET /chat/sessions` — works offline
40	        // (cache)" — same cursor-null-page cache-fallback convention
41	        // `EntriesRepositoryImpl.list()` already uses; every other
42	        // `Failure` (e.g. `authExpired`) propagates as `Left`, unmapped.
43	        if (failure is NetworkOffline || failure is NetworkTimeout) {
44	          return _cachedSessions();
45	        }
46	        return left(failure);
47	      },
48	      (dtos) async {
49	        try {
50	          await _sessionsBox.putAll({
51	            for (final dto in dtos) dto.id: dto.toJson(),
52	          });
53	        } catch (error) {
54	          // A thrown Hive/disk exception must never escape unmapped
55	          // (RNF09) — same fallback `EntriesRepositoryImpl`'s own writes
56	          // already use.
57	          return left(Failure.malformedResponse(message: error.toString()));
58	        }
59	        return right(dtos.map((dto) => dto.toEntity()).toList());
60	      },
61	    );
62	  }
63	
64	  @override
65	  Future<Either<Failure, ChatSession>> createSession() async {
66	    final result = await _remoteDataSource.createSession();
67	    return result.match(
68	      // Blocked offline (`requirements.md`) — no cache fallback, unlike
69	      // [listSessions]/[listMessages]: every `Failure` propagates as
70	      // `Left`, unmapped.
71	      (failure) async => left(failure),
72	      (dto) async {
73	        // A local cache-write failure must never mask an already-
74	        // succeeded remote create: the session exists server-side
75	        // regardless, so surfacing `left(...)` here would show the user
76	        // a bootstrap error for an operation that actually succeeded
77	        // (it would simply be re-fetched via `listSessions()` next
78	        // time). Best-effort only.
79	        try {
80	          await _sessionsBox.put(dto.id, dto.toJson());
81	        } catch (_) {
82	          // Intentionally ignored — see above.
83	        }
84	        return right(dto.toEntity());
85	      },
86	    );
87	  }
88	
89	  @override
90	  Future<Either<Failure, List<ChatMessage>>> listMessages(
91	    String sessionId,
92	  ) async {
93	    final result = await _remoteDataSource.listMessages(sessionId);
94	    return result.match(
95	      (failure) async {
96	        // `requirements.md`: "`GET /chat/sessions/:id/messages` — works
97	        // offline (cache)" — same convention [listSessions] above uses.
98	        if (failure is NetworkOffline || failure is NetworkTimeout) {
99	          return _cachedMessages(sessionId);
100	        }
101	        return left(failure);
102	      },
103	      (dtos) async {
104	        try {
105	          await _messagesBox.putAll({
106	            for (final dto in dtos) dto.id: dto.toJson(),
107	          });
108	        } catch (error) {
109	          return left(Failure.malformedResponse(message: error.toString()));
110	        }
111	        return right(dtos.map((dto) => dto.toEntity()).toList());
112	      },
113	    );
114	  }
115	
116	  @override
117	  Stream<Either<Failure, ChatStreamEvent>> sendMessage(
118	    String sessionId,
119	    String content,
120	  ) =>
121	      // Design Notes: "Chat holds no local write queue" — a pure
122	      // passthrough, no Hive persistence of sent messages for this story.
123	      _remoteDataSource.sendMessage(sessionId, content);
124	
125	  @override
126	  Stream<Either<Failure, ChatStreamEvent>> retryMessage(
127	    String sessionId,
128	    String userMessageId,
129	  ) =>
130	      // spec-6-3 — same pure-passthrough rationale as [sendMessage] above.
131	      _remoteDataSource.retryMessage(sessionId, userMessageId);
132	
133	  @override
134	  Future<Either<Failure, ChatInsight?>> generateInsight(
135	    String sessionId, {
136	    required InsightTriggerType triggerType,
137	    required String triggerKey,
138	  }) async {
139	    // spec-6-5 — pure passthrough (no Hive, mirrors [sendMessage]/
140	    // [retryMessage] above): [Left] is unmapped; a [Right] is only ever
141	    // turned into a real [ChatInsight] when the backend's own `status`
142	    // is `'ready'` (RF08) — anything else (`generating`/`failed`/
143	    // `dismissed`), or a `'ready'` response with no non-blank `content`
144	    // (shouldn't happen, defensive — `openapi.yaml` doesn't promise
145	    // `minLength: 1` on this field), maps to `Right(null)` instead of a
146	    // [Failure].
147	    final result = await _remoteDataSource.generateInsight(
148	      sessionId,
149	      triggerType: triggerType.wireValue,
150	      triggerKey: triggerKey,
151	    );
152	    return result.match(
153	      (failure) => left(failure),
154	      (dto) => right(
155	        dto.status == 'ready' && (dto.content?.trim().isNotEmpty ?? false)
156	            ? ChatInsight(id: dto.id, content: dto.content!)
157	            : null,
158	      ),
159	    );
160	  }
161	
162	  @override
163	  Future<Either<Failure, Unit>> clearLocalCache() async {
164	    // Review finding: the two boxes are cleared independently (each in its
165	    // own try/catch) rather than sequentially inside one shared try/catch —
166	    // otherwise a throw clearing `_sessionsBox` would skip `_messagesBox.
167	    // clear()` entirely, leaving it uncleared on logout with no record of
168	    // why. Both are always attempted; `Left` only if at least one failed.
169	    // Code-review patch: each error is tagged with which box produced it —
170	    // an untagged `firstError` would make a real disk-full failure
171	    // unattributable from logs alone.
172	    String? firstError;
173	    try {
174	      await _sessionsBox.clear();
175	    } catch (error) {
176	      firstError = 'chat_sessions: $error';
177	    }
178	    try {
179	      await _messagesBox.clear();
180	    } catch (error) {
181	      firstError ??= 'chat_messages: $error';
182	    }
183	    if (firstError != null) {
184	      // Same RNF09 rationale as every other Hive-write guard in this file.
185	      return left(Failure.malformedResponse(message: firstError));
186	    }
187	    return right(unit);
188	  }
189	
190	  /// [listSessions]'s own offline/timeout fallback — a full `chat_
191	  /// sessions` Hive box dump, sorted `updatedAt` desc (so `ChatCubit.
192	  /// init()`'s own "reuse the most recent session" pick is already
193	  /// correctly ordered even against the cache), same "always `Right`,
194	  /// even if empty" convention `EntriesRepositoryImpl._offlineFallback()`
195	  /// already uses. Each entry is decoded independently — one corrupt
196	  /// cached entry is skipped, never discarding every other (valid)
197	  /// session in the box over it.
198	  Either<Failure, List<ChatSession>> _cachedSessions() {
199	    final sessions = <ChatSession>[];
200	    for (final json in _sessionsBox.values) {
201	      try {
202	        sessions.add(
203	          ChatSessionDto.fromJson(Map<String, dynamic>.from(json)).toEntity(),
204	        );
205	      } catch (_) {
206	        // Skip this one corrupt entry — see doc above.
207	      }
208	    }
209	    // Review fix: `tryParse` (never `parse`) — same crash-safe pattern as
210	    // the sibling "most recent session" sorts in `ChatCubit._bootstrap`
211	    // and `_ConversasSection`; a malformed cached `updatedAt` must never
212	    // throw out of this offline-cache fallback (RNF09).
213	    sessions.sort(
214	      (a, b) => (DateTime.tryParse(b.updatedAt) ?? DateTime(0)).compareTo(
215	        DateTime.tryParse(a.updatedAt) ?? DateTime(0),
216	      ),
217	    );
218	    return right(sessions);
219	  }
220	
221	  /// [listMessages]'s own offline/timeout fallback — a full `chat_
222	  /// messages` Hive box dump filtered to [sessionId] and sorted `seq`
223	  /// ascending (the backend's own "ordered by seq", `openapi.yaml`), same
224	  /// "always `Right`, even if empty" convention [_cachedSessions] above
225	  /// uses. Each entry is decoded independently, same corrupt-entry
226	  /// isolation as [_cachedSessions].
227	  Either<Failure, List<ChatMessage>> _cachedMessages(String sessionId) {
228	    final messages = <ChatMessage>[];
229	    for (final json in _messagesBox.values) {
230	      try {
231	        final message = ChatMessageDto.fromJson(Map<String, dynamic>.from(json))
232	            .toEntity();
233	        if (message.sessionId == sessionId) {
234	          messages.add(message);
235	        }
236	      } catch (_) {
237	        // Skip this one corrupt entry — see doc above.
238	      }
239	    }
240	    messages.sort((a, b) => a.seq.compareTo(b.seq));
241	    return right(messages);
242	  }
243	}
